import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../state/auth_state.dart';
import '../../core/app_theme.dart';
import '../../widgets/devhub_widgets.dart';
class SkillsScreen extends StatelessWidget{const SkillsScreen({super.key});
 @override Widget build(BuildContext context){final auth=context.watch<AuthState>();return ListView(padding:const EdgeInsets.all(18),children:[Text('My skills',style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:5),const Text('Skills are extracted from repository evidence and can be maintained manually.',style:TextStyle(color:AppColors.muted)),const SizedBox(height:20),...['Frontend','Backend','Database','DevOps','Other'].map((cat){final list=auth.skills.where((s)=>(s['category']??'Other').toString().toLowerCase()==cat.toLowerCase()).toList();if(list.isEmpty)return const SizedBox.shrink();return Padding(padding:const EdgeInsets.only(bottom:18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[SectionTitle(cat,subtitle:'${list.length} skills'),const SizedBox(height:10),Panel(child:Column(children:list.map((s){final weight=(s['weight']??s['normalizedScore']??s['score']??.5);final n=weight is num?weight.toDouble():double.tryParse('$weight')??.5;final pct=n>1?n/100:n;return Padding(padding:const EdgeInsets.only(bottom:13),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text('${s['name']??'Skill'}',style:const TextStyle(fontWeight:FontWeight.w600))),Text('${(pct*100).round()}%',style:const TextStyle(color:AppColors.muted))]),const SizedBox(height:7),ClipRRect(borderRadius:BorderRadius.circular(10),child:LinearProgressIndicator(value:pct.clamp(0,1),minHeight:7,backgroundColor:AppColors.line,color:AppColors.violet))]));}).toList()))]));}),if(auth.skills.isEmpty)const Panel(child:Text('No skills found. Sync GitHub data to extract skills.',style:TextStyle(color:AppColors.muted)))]);}
}
